import base64

# Your full Base64 string
encoded_string = ""

# Decode it
decoded_bytes = base64.b64decode(encoded_string)

# Save the binary data to a file
with open("decoded_data.bin", "wb") as f:
    f.write(decoded_bytes)
    
print("File saved as decoded_data.bin. You can now analyze it using file signature tools or hex editors.")